def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_row = next(
        (r for r in range(h) if len(set(grid[r])) == 1),
        None
    )

    if divider_row is not None:
        top = grid[:divider_row]
        bottom = grid[divider_row + 1:]
        nrows = min(len(top), len(bottom))
        return [
            [2 if top[r][c] != 0 and bottom[r][c] != 0 else 0
             for c in range(w)]
            for r in range(nrows)
        ]

    divider_col = next(
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    )
    left_width = divider_col
    right_width = w - divider_col - 1
    ncols = min(left_width, right_width)

    return [
        [2 if grid[r][c] != 0 and grid[r][divider_col + 1 + c] != 0 else 0
         for c in range(ncols)]
        for r in range(h)
    ]

