def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not cells:
        return out
    rmid = (min(r for r, c in cells) + max(r for r, c in cells)) / 2
    cmid = (min(c for r, c in cells) + max(c for r, c in cells)) / 2

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != color:
                    continue

                # The two off-diagonal corners must be empty.
                if grid[r][c + dc] != bg or grid[r + dr][c] != bg:
                    continue

                pr, pc = r + dr / 2, c + dc / 2
                vr, vc = pr - rmid, pc - cmid
                if vr == 0 or vc == 0:
                    continue
                sr = 1 if vr > 0 else -1
                sc = 1 if vc > 0 else -1
                if sr != dr and sr != -dr:
                    continue
                if sc != dc and sc != -dc:
                    continue

                # Extend only outward from the overall motif.
                if sr == dr and sc == dc:
                    ar, ac = rr, cc
                elif sr == -dr and sc == -dc:
                    ar, ac = r, c
                else:
                    continue

                nr, nc = ar + sr, ac + sc
                while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                    out[nr][nc] = color
                    nr += sr
                    nc += sc
    return out

