def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    features = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: c - r,
    ]

    best = None
    for period in range(1, 2 * (h + w) + 1):
        for feature in features:
            pattern = {}
            valid = True
            for r, c, color in points:
                key = feature(r, c) % period
                if key in pattern and pattern[key] != color:
                    valid = False
                    break
                pattern[key] = color
            if not valid:
                continue

            groups = {}
            for r, c, _ in points:
                key = feature(r, c)
                groups[key] = groups.get(key, 0) + 1
            support = sum(n * (n - 1) // 2 for n in groups.values())

            candidate = (period, -support, feature, pattern)
            if best is None or candidate[:2] < best[:2]:
                best = candidate
        if best is not None:
            break

    if best is None:
        return [row[:] for row in grid]

    _, _, feature, pattern = best
    return [
        [pattern[feature(r, c) % best[0]] for c in range(w)]
        for r in range(h)
    ]

