def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if grid[r][0] != bg and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))]

    def spans(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    best = None
    best_count = -1
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            if count > best_count:
                best_count = count
                best = (r0, r1, c0, c1)

    if not best or best_count == 0:
        return [row[:] for row in grid]

    r0, r1, c0, c1 = best
    pattern = [
        (r - r0, c - c0, grid[r][c])
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] != bg
    ]

    out = [row[:] for row in grid]
    for a, b in row_spans:
        for x, y in col_spans:
            for r in range(a, b):
                for c in range(x, y):
                    out[r][c] = bg
            for dr, dc, color in pattern:
                if a + dr < b and x + dc < y:
                    out[a + dr][x + dc] = color
    return out

