def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Fill diagonal segments joining aligned 1s and note their orientations.
    segment_cells = set()
    orientations = {}
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc):
                continue
            step_r = 1 if dr > 0 else -1
            step_c = 1 if dc > 0 else -1
            for k in range(abs(dr) + 1):
                p = (r1 + k * step_r, c1 + k * step_c)
                segment_cells.add(p)
                orientations.setdefault(p, set()).add(step_r * step_c)
                if grid[p[0]][p[1]] == 4:
                    out[p[0]][p[1]] = 1

    # A 6 on a 1-segment draws a full diagonal perpendicular to that segment.
    for r, c in sixes:
        for slope in orientations.get((r, c), ()):
            for rr in range(h):
                cc = (r + c - rr) if slope == 1 else (c + rr - r)
                if 0 <= cc < w and grid[rr][cc] not in (1, 6):
                    out[rr][cc] = 6

    return out

